// Clase base
public class Animal
{
    public string Name;
    protected int Health;

    public Animal(string name, int health)
    {
        Name = name;
        Health = health;
    }

    public void Breathe()
    {
        Debug.Log(Name + " is breathing.");
    }
}

// Clase derivada de Animal
public class Dog : Animal
{
    public string Breed;

    public Dog(string name, string breed) : base(name, 100)
    {
        Breed = breed;
    }

    public void Bark()
    {
        Debug.Log(Name + " says: Woof!");
    }
}

// Herencia multinivel: GoldenRetriever es un Dog que es un Animal
public class GoldenRetriever : Dog
{
    public GoldenRetriever(string name) : base(name, "Golden Retriever") { }

    public void Fetch()
    {
        Debug.Log(Name + " fetches the ball!");
    }
}

public class Enemy
{
    public string EnemyName;
    public int MaxHealth;

    // Constructor de la clase base
    public Enemy(string name, int maxHealth)
    {
        EnemyName = name;
        MaxHealth = maxHealth;
    }
}

public class Boss : Enemy
{
    public int Phase;

    // base(name, maxHealth) llama al constructor de Enemy ANTES de ejecutar este cuerpo
    public Boss(string name, int phase) : base(name, 500)
    {
        Phase = phase;
    }
}

